trials.server_config:
daemon off;
master_process on;
pid /tmp/pace-gateway-bench-ieglduq2/nginx.pid;
error_log /tmp/pace-gateway-bench-ieglduq2/error.log warn;
worker_processes 1;
events { worker_connections 8192; }
http {
    access_log off;
    default_type application/octet-stream;
    sendfile on;
    tcp_nodelay on;
    keepalive_timeout 60;
    keepalive_requests 10000000;
    client_body_temp_path /tmp/pace-gateway-bench-ieglduq2/body;
    proxy_temp_path /tmp/pace-gateway-bench-ieglduq2/proxy_temp;
    upstream origin {
        server 127.0.0.1:41163 max_fails=1 fail_timeout=1s;
        server 127.0.0.1:55243 max_fails=1 fail_timeout=1s;
        keepalive 256;
    }
    server { listen 127.0.0.1:59625 reuseport; location / { proxy_pass http://origin;
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_next_upstream off;
            proxy_buffering on;
            proxy_buffers 8 64k;
            proxy_busy_buffers_size 128k;
            proxy_max_temp_file_size 0;
            proxy_connect_timeout 30s;
            proxy_read_timeout 30s; } }
}

